mapper.select:
SELECT id, name, description, color, type, is_system as isSystem, organization_id as organizationId,
       created_by as createdBy, created_time as createdTime, updated_by as updatedBy, updated_time as updatedTime
FROM customer_tag
WHERE name = #{name}
  AND organization_id = #{orgId}

mapper.delete:
DELETE FROM customer_tag_relation
WHERE customer_id = #{customerId}
  AND tag_id = #{tagId}
